-- id:       view-department-workload
-- title:    Department workload (view)
-- concept:  vw_department_workload · aggregate view with FILTER
-- rubric:   8 · View
-- purpose:  Open, in-progress, escalated and breached counts per department with historical SLA performance. security_invoker, so a ward admin sees only their ward.
-- GENERATED by web/scripts/export-queries.ts from src/lib/data/mock/lab.ts. Edit there, then run npm run db:queries.

SELECT department_name, waiting, in_progress, escalated, breached_now,
       avg_resolution_hours, sla_met_pct, active_staff
FROM vw_department_workload
ORDER BY breached_now DESC, department_name;
